<?php
use Illuminate\Support\Facades\Route;
use App\Http\Controllers\{AuditController,AuthController,DashboardController,FindingController,ReportController,UserController};
Route::get('/',fn()=>redirect()->route(auth()->check()?'dashboard':'login'));
Route::middleware('guest')->group(function(){Route::get('/login',[AuthController::class,'show'])->name('login');Route::post('/login',[AuthController::class,'login'])->name('login.store');});
Route::middleware(['auth','syncFindingStatuses'])->group(function(){Route::post('/logout',[AuthController::class,'logout'])->name('logout');Route::get('/dashboard',[DashboardController::class,'index'])->name('dashboard');Route::resource('findings',FindingController::class)->except(['destroy']);Route::post('/findings/{finding}/progress',[FindingController::class,'updateProgress'])->name('findings.progress');Route::post('/findings/{finding}/evidence',[FindingController::class,'evidence'])->name('findings.evidence');Route::get('/findings-export',[FindingController::class,'export'])->name('findings.export');Route::get('/reports',[ReportController::class,'index'])->name('reports');Route::middleware('admin')->resource('audits',AuditController::class)->only(['index','store','update']);Route::middleware('admin')->get('/users',[UserController::class,'index'])->name('users.index');Route::middleware('admin')->post('/users',[UserController::class,'store'])->name('users.store');Route::middleware('admin')->put('/users/{user}',[UserController::class,'update'])->name('users.update');Route::middleware('admin')->delete('/users/{user}',[UserController::class,'destroy'])->name('users.destroy');});
